import { v, query } from "@/lib/validator";
import { db } from "@/lib/db";

export default query({
  args: {
    from: v.datetime(),
    to: v.datetime(),
  },
  handler: async ({ from, to }) => {
    const start = new Date(from).getTime();
    const end = new Date(to).getTime();

    if (!Number.isFinite(start) || !Number.isFinite(end)) {
      throw new Error("busySlots: некорректные значения from/to");
    }
    if (end <= start) {
      throw new Error("busySlots: интервал to должен быть позже from");
    }

    const maxWindowMs = 400 * 24 * 60 * 60 * 1000;
    if (end - start > maxWindowMs) {
      throw new Error("busySlots: интервал слишком большой (максимум 400 дней)");
    }

    const rows = await db.booking.findMany({
      where: {
        starts_at: { lt: to },
        ends_at: { gt: from },
        status: { in: ["pending", "confirmed"] },
      },
      select: { starts_at: true, ends_at: true, seat: true },
    });

    return rows.map((r) => ({
      starts_at: r.starts_at,
      ends_at: r.ends_at,
      seat: r.seat ?? null,
    }));
  },
});
